def transform(grid):
    g=[list(r) for r in grid]
    h,w=len(g),len(g[0])
    bg=max(set(v for r in g for v in r), key=lambda v:sum(x==v for r in g for x in r))
    fg=[v for v in set(v for r in g for v in r) if v!=bg]
    if len(fg)!=1: return g
    c=fg[0]
    active=[i for i,r in enumerate(g) if c in r]
    # Separate repeated figures by blank rows.
    bands=[]
    for i in active:
        if not bands or i>bands[-1][-1]+1: bands.append([i])
        else: bands[-1].append(i)
    if len(bands)!=2 or len(bands[0])!=len(bands[1]): return g
    a,b=bands
    # Infer the horizontal offset between copies from the shared prefix.
    # The compact copy is the one to extend; align its left edge to the other.
    def extent(rows):
        return max((j for i in rows for j,x in enumerate(g[i]) if x==c),default=-1)
    ea,eb=extent(a),extent(b)
    short,long=(a,b) if ea<eb else (b,a)
    es,el=min(ea,eb),max(ea,eb)
    # Find relative horizontal offset by maximum overlap of foreground masks.
    best=(float('-inf'),0)
    for shift in range(-4,5):
        score=0
        for rs,rl in zip(a,b):
            for x in range(w):
                y=x-shift
                if 0<=y<w: score += (g[rs][x]==c)==(g[rl][y]==c)
        if score>best[0]: best=(score,shift)
    shift=best[1]
    if es==el:
        # If both copies occupy the same width, highlight the extra foreground
        # in the denser copy (the other copy supplies the matching pattern).
        ca=sum(x==c for i in a for x in g[i]); cb=sum(x==c for i in b for x in g[i])
        target,ref=(a,b) if ca>cb else (b,a)
        for rt,rr in zip(target,ref):
            for x in range(w):
                y=x-shift
                if 0<=y<w and g[rt][x]==c and g[rr][y]!=c: g[rt][x]=1
        return g
    # Mark the longer copy's rightward continuation on the shorter copy.
    for rs,rl in zip(short,long):
        for x in range(es+1,w):
            y=x-shift
            if 0<=y<w and g[rl][y]==c and g[rs][x]==bg:
                g[rs][x]=1
    return g

